package com.ruoyi.paicli.service;

import com.ruoyi.paicli.domain.*;
import java.util.*;

/** 清理先报告完整派生缓存，再按冻结的HEAD/ref/commit及正式快照版本独立批准。 */
public final class PcSnapshotClean {
    private final PcStore store;
    public PcSnapshotClean(PcStore store){this.store=store;}
    public List<Map<String,Object>> targets(long workspace,long runner){List<Map<String,Object>> result=new ArrayList<>();for(PcRecord row:store.mapper.list(PcTable.SNAPSHOT,workspace,null,null,"READY"))if(row.getKind().equals("SNAPSHOT")&&Objects.equals(row.getRunnerId(),runner)){Map<String,Object> data=store.data(row);String commit=PcJson.text(data,"commitId");if(commit.isBlank())commit=PcJson.text(data,"snapshotId");if(!commit.matches("[a-f0-9]{40}"))throw PcException.conflict("正式快照缺真实commit，不能按不完整清单清理");result.add(Map.of("snapshotMetadataId",row.getId().toString(),"snapshotId",commit,"snapshotVersion",row.getVersion()));}result.sort(Comparator.comparing(m->m.get("snapshotMetadataId").toString()));return result;}
    public Map<String,Object> previewArguments(long workspace,long runner){return Map.of("range","current","targets",targets(workspace,runner),"runnerId",String.valueOf(runner),"rootFingerprint",store.data(store.require(PcTable.WORKSPACE,workspace,false)).get("rootFingerprint"));}
    public void validate(PcRecord task,Map<String,Object> arguments){if(!"current".equals(arguments.get("range"))||!String.valueOf(task.getRunnerId()).equals(arguments.get("runnerId"))||!Objects.equals(store.data(store.require(PcTable.WORKSPACE,task.getWorkspaceId(),false)).get("rootFingerprint"),arguments.get("rootFingerprint")))throw PcException.deny("快照清理必须绑定单一当前工作区和Runner根");if(!store.json.hash(targets(task.getWorkspaceId(),task.getRunnerId())).equals(store.json.hash(arguments.get("targets"))))throw PcException.conflict("正式快照集合或版本变化，请重新预览并批准清理");if("SNAPSHOT_CLEAN".equals(store.data(task).get("operation"))){if(!(arguments.get("cleanPreview") instanceof Map<?,?>))throw PcException.deny("清理执行必须有已登记的完整实际预览");PcRecord preview=store.require(PcTable.SNAPSHOT,PcJson.number(arguments,"cleanPreviewRecordId"),true);Map<String,Object> data=store.data(preview);if(!preview.getKind().equals("CLEAN_PREVIEW")||!preview.getState().equals("BOUND_CLEANUP")||!Objects.equals(preview.getWorkspaceId(),task.getWorkspaceId())||!Objects.equals(preview.getOwnerId(),task.getOwnerId())||!Objects.equals(preview.getRunnerId(),task.getRunnerId())||!Objects.toString(data.get("cleanupTaskId"),"").equals(task.getId().toString())||!store.json.hash(data.get("cleanPreview")).equals(store.json.hash(arguments.get("cleanPreview"))))throw PcException.deny("清理证明未正式绑定当前任务");Map<String,Object> frozen=PcJson.object(data,"frozenArguments");for(String field:List.of("range","targets","runnerId","rootFingerprint"))if(!store.json.hash(frozen.get(field)).equals(store.json.hash(arguments.get(field))))throw PcException.conflict("清理批准范围不同于正式预览");}if(arguments.get("cleanPreview") instanceof Map<?,?>){Map<String,Object> proof=PcJson.object(arguments,"cleanPreview");validateProof(task,arguments,proof);}}
    public void validateProof(PcRecord task,Map<String,Object> arguments,Map<String,Object> proof){
        if(!"CLEAN_PREVIEW".equals(proof.get("operation"))||!"current".equals(proof.get("range"))||PcJson.number(proof,"previewVersion")!=1||!PcJson.text(proof,"repositoryManifestHash").matches("[a-f0-9]{64}")||PcJson.number(proof,"fileCount")<0||PcJson.number(proof,"totalBytes")<0||!store.json.hash(arguments.get("targets")).equals(store.json.hash(proof.get("knownTargets"))))throw PcException.invalid("清理预览缺少实际缓存清单或冻结目标版本");String head=PcJson.text(proof,"head");if(!head.isBlank()&&!head.matches("[a-f0-9]{40}"))throw PcException.invalid("清理预览HEAD不是实际commit");if(!(proof.get("commits") instanceof List<?> commits)||commits.size()>100000||!(proof.get("unregistered") instanceof List<?> unknown)||unknown.size()>100000||!(proof.get("refs") instanceof List<?> refs)||refs.size()>100000)throw PcException.invalid("清理需完整commit/ref/unknown清单，不允许部分缓存");Set<String> ids=new HashSet<>();for(Object value:commits){String id=Objects.toString(value,"");if(!id.matches("[a-f0-9]{40}")||!ids.add(id))throw PcException.invalid("清理commit清单非法或重复");}if(!head.isBlank()&&!ids.contains(head))throw PcException.invalid("HEAD不在清理commit清单");Set<String> names=new HashSet<>();for(Object value:refs){if(!(value instanceof Map<?,?> ref)||!Objects.toString(ref.get("objectId"),"").matches("[a-f0-9]{40}")||!ids.contains(ref.get("objectId"))||Objects.toString(ref.get("name"),"").isBlank()||Objects.toString(ref.get("name"),"").length()>4096||!names.add(ref.get("name").toString()))throw PcException.invalid("清理ref清单非法或重复");}Set<String> known=new HashSet<>();for(Object value:(List<?>)arguments.get("targets")){Map<?,?> target=(Map<?,?>)value;String commit=target.get("snapshotId").toString();if(!ids.contains(commit))throw PcException.conflict("正式快照不在实际缓存清单，不能清理失配目录");known.add(commit);}Set<String> expected=new HashSet<>(ids);expected.removeAll(known);Set<String> actual=new HashSet<>();for(Object value:unknown)if(!actual.add(Objects.toString(value,"")))throw PcException.invalid("未登记backup重复");if(!expected.equals(actual))throw PcException.conflict("未知backup列表与完整commit集合不符");if(store.json.write(proof).getBytes(java.nio.charset.StandardCharsets.UTF_8).length>16L*1024*1024)throw PcException.invalid("清理证明超过16MiB，不能批准部分缓存");
    }
    public void preview(PcRecord task,Map<String,Object> payload){Map<String,Object> arguments=PcJson.object(store.data(task),"arguments");validate(task,arguments);validateProof(task,arguments,payload);Map<String,Object> data=new LinkedHashMap<>();data.put("cleanPreview",payload);data.put("frozenArguments",arguments);data.put("previewOwnerId",task.getOwnerId().toString());PcRecord row=store.insert(PcTable.SNAPSHOT,task.getWorkspaceId(),task.getOwnerId(),task.getId(),task.getSessionId(),task.getRunnerId(),"CLEAN_PREVIEW","DERIVED_READY",null,data);row.setExpiresAt(store.clock.instant().plusSeconds(300));store.save(PcTable.SNAPSHOT,row,data);}
    public void cleaned(PcRecord task,Map<String,Object> payload){Map<String,Object> arguments=PcJson.object(store.data(task),"arguments");validate(task,arguments);Map<String,Object> proof=PcJson.object(arguments,"cleanPreview"),backup=PcJson.object(payload,"backup");if(!"current".equals(payload.get("range"))||!Objects.equals(proof.get("repositoryManifestHash"),payload.get("repositoryManifestHash"))||!store.json.hash(arguments.get("targets")).equals(store.json.hash(payload.get("knownTargets")))||!Objects.equals(proof.get("repositoryManifestHash"),backup.get("manifestHash"))||!PcJson.text(backup,"archiveId").matches("[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}")||!PcJson.text(backup,"sha256").matches("[a-f0-9]{64}")||!Boolean.TRUE.equals(backup.get("restorable"))||PcJson.number(backup,"fileCount")!=PcJson.number(proof,"fileCount")||PcJson.number(backup,"totalBytes")!=PcJson.number(proof,"totalBytes"))throw PcException.conflict("清理回执必须有先行完成且可恢复的私有备份和同一完整范围");for(Object value:(List<?>)arguments.get("targets")){Map<?,?> target=(Map<?,?>)value;PcRecord row=store.require(PcTable.SNAPSHOT,Long.parseLong(target.get("snapshotMetadataId").toString()),true);Map<String,Object> data=store.data(row);data.put("cleanupTaskId",task.getId().toString());data.put("cleanedAt",store.clock.instant().toString());data.put("backup",backup);row.setState("CLEANED");store.save(PcTable.SNAPSHOT,row,data);}}
}
